// Ask the user for their age. Then, come up with 5 life milestones that occur at certain ages (ex: you can run for president at 35). Use ternary operators to print whether or not they qualify for these milestones based on their age!

// Solution

let age = +prompt("How old are you?");

let isBaby = age <= 2 ? "You are a baby." : "You are not a baby.";

let isToddler =
  age > 2 && age < 5 ? "You are a toddler." : "You are not a toddler.";

let canDrive =
  age >= 16 ? "You can legally drive." : "You cannot legally drive.";

let canRunForPresident =
  age >= 35 ? "You can run for president." : "You cannot run for president.";

let qualifyForMedicare =
  age >= 65 ? "You qualify for Medicare." : "You do not qualify for Medicare.";

printToScreen("According to your age:");

printToScreen(isBaby);
printToScreen(isToddler);
printToScreen(canDrive);
printToScreen(canRunForPresident);
printToScreen(qualifyForMedicare);

