/*
Welcome to the Juni department store! Everything in the store is discounted for students!

The student discount is:
0% for non-students,
10% for elementary school students,
12% for middle school students,
14% for high school students,
16% for college students, and
20% for Juni students!

However, in true Juni fashion, there is a mathematical twist:

If the price after the discount, rounded down to the nearest integer, is a perfect square or a prime number, we apply the discount one more time. Otherwise, we increase the price until it is a perfect square or a prime number (whichever comes first).

Write a program that will ask the user for the cost of their items and the type of student they are. Use a combination of functions, ternary operators, and if-statements to help you calculate their discount. Finally, use printToScreen() to display their final price.
*/

// Solution

const isPerfectSquare = (num) => {
  let root = Math.sqrt(num);
  let rootFloor = Math.floor(root);
  return root === rootFloor ? true : false;
};

const isPrime = (num) => {
  if (num == 1) {
    return true;
  }
  for (let i = 2; i < num; i++) {
    if (num % i === 0) {
      return false;
    }
  }
  return true;
};

const increasePrice = (num) => {
  while (!isPerfectSquare(num) && !isPrime(num)) {
    num++;
  }
  return num;
};

const applyDiscount = (price, percentDiscount) => {
  return price * ((100 - percentDiscount) / 100);
};


let price = +prompt("How much did your items cost?");
let studentType = prompt("What type of student are you? Type elementary/middle/high/college/juni/none.");

// null check
studentType = studentType ? studentType.toLowerCase() : "none";

let discount = 0;
if (studentType === "elementary") {
  discount = 10;
} else if (studentType === "middle") {
  discount = 12;
} else if (studentType === "high") {
  discount = 14;
} else if (studentType === "college") {
  discount = 16;
} else if (studentType === "juni") {
  discount = 20;
}

price = applyDiscount(price, discount);

if (isPerfectSquare(Math.floor(price)) || isPrime(Math.floor(price))) {
  price = applyDiscount(price, discount);
} else {
  price = increasePrice(price);
}

printToScreen(`Your final price is: $${price.toFixed(2)}`);

