/*
There are many interesting numbers out there! For each of these examples, write a function that takes in a number input and returns true if the number meets the stated property, false otherwise.

1. Self-Dividing Number: a positive integer that is divisible by every digit it contains. 
Example: 128 is a self-dividing number because it is divisible by 1, 2, and 8.
Use printToScreen() to print all the self-dividing numbers from 300 to 700.

2. Perfect Number: a positive integer that is equal to the sum of all its positive divisors except itself.
Example: 28 is a perfect number because its divisors less than 28 are 1, 2, 4, 7, and 14 and 1 + 2 + 4 + 7 + 14 = 28.
Use printToScreen() to print all the perfect numbers from 1 to 9000.

3. Palindrome Number: a positive integer that reads the same backward as forward.
Example: 121 and 22 are palindrome numbers.
Use printToScreen() to print all the palindrome numbers from 700 to 2000.
*/

// Solution

const isSelfDividing = (num) => {
  let cur = num;
  while (cur > 0) {
    let divisor = cur % 10;
    cur = Math.floor(cur / 10);
    if (num % divisor !== 0) {
      return false;
    }
  }
  return true;
};

printToScreen("Self Dividing Numbers:");
for (let i = 300; i < 701; i++) {
  if (isSelfDividing(i)) {
    printToScreen(i);
  }
}


// Less Efficient Perfect Number Solution
const isPerfect = (num) => {
  let sum = 0;
  for (let i = 1; i < num; i++) {
    if (num % i === 0) {
      sum += i;
    }
  }
  return sum === num;
};

// Efficient Perfect Number Solution (for more advanced students)
const isPerfect2 = (num) => {
  if (num === 1) {
    return false;
  }
  let sum = 0;
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      sum += i + num / i;
    }
  }
  sum++;
  return sum === num;
};

printToScreen("Perfect Numbers: ");
for (let i = 1; i < 9001; i++) {
  if (isPerfect2(i)) {
    printToScreen(i);
  }
}


const isPalindrome = (num) => {
  if (num < 0) {
    return false;
  }
  if (num < 10) {
    return true;
  }
  if (num % 10 === 0) {
    return false;
  }
  let rev = 0;
  while (num >= 10) {
    let cur = num % 10;
    rev = rev * 10 + cur;
    if (num === rev) {
      return true; // check before changing x (for nums with odd number of digits)
    }
    num = Math.floor(num/10);
    if (num === rev) {
      return true; // check after changing x (for nums with even number of digits)
    }
    if (num < rev) {
      return false;
    }
  }
  return false;
}

printToScreen("Palindrome Numbers: ");
for (let i = 700; i < 2001; i++) {
  if (isPalindrome(i)) {
    printToScreen(i);
  }
}



